<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import AppHeader from '../components/AppHeader.vue';
import GuideLink from '../components/GuideLink.vue';
import {useAccountStore} from '../stores/account';
import {loadWorkspace,saveWorkspace,emptyWorkspace,type Course} from '../services/clientWorkspace';
import {parseTimetableText,syntheticCourses,validateCourse,courseConflicts} from '../services/timetable';
import {api} from '../services/api';
import {requirePrivacyReview} from '../services/privacyGuard';
const account=useAccountStore(),owner=computed(()=>account.user?.id||'offline'),data=ref(emptyWorkspace(owner.value)),error=ref(''),message=ref('');
const semesterStart=ref('2026-09-07'),semesterEnd=ref('2027-01-10'),text=ref(''),candidates=ref<Course[]>([]),unparsed=ref<string[]>([]),consent=ref(false),file=ref<File|null>(null);
const form=ref({title:'',weekday:1,startTime:'08:00',endTime:'10:00',startWeek:1,endWeek:18,parity:'all' as Course['parity']});
let loadVersion=0;async function reload(){const version=++loadVersion,identity=owner.value;data.value=emptyWorkspace(identity);try{const loaded=await loadWorkspace(identity);if(version===loadVersion&&identity===owner.value)data.value=loaded}catch(e:any){if(version===loadVersion)error.value=e.message}}
onMounted(reload);watch(owner,reload);
async function persist(){data.value=await saveWorkspace(data.value)}
async function add(){try{const id=crypto.randomUUID();const c:Course={...form.value,id,semesterStart:semesterStart.value,semesterEnd:semesterEnd.value,evidence:{id:'block:client:'+id,text:`用户填写课表：${form.value.title}，周${form.value.weekday} ${form.value.startTime}-${form.value.endTime}，${form.value.startWeek}-${form.value.endWeek}周 ${form.value.parity}`},cancelledDates:[]};validateCourse(c);data.value.courses.push(c);await persist();message.value='课程已保存在本机，排程会避开上课时间。'}catch(e:any){error.value=e.message}}
function parse(){try{const result=parseTimetableText(text.value,semesterStart.value,semesterEnd.value);candidates.value=result.courses;unparsed.value=result.unparsed}catch(e:any){error.value=e.message}}
async function confirmCourse(c:Course){try{validateCourse(c);if(!data.value.courses.some(row=>row.id===c.id))data.value.courses.push(c);await persist();candidates.value=candidates.value.filter(row=>row.id!==c.id);message.value='课表候选已确认。'}catch(e:any){error.value=e.message}}
async function remove(id:string){data.value.courses=data.value.courses.filter(c=>c.id!==id);await persist()}
async function demo(){data.value.courses=[...data.value.courses,...syntheticCourses()];await persist();message.value='合成课表已加入，明确标记为演示数据。'}
async function upload(){try{if(!account.signedIn)throw Error('文件解析需要登录，文本整理可离线进行');if(!file.value)throw Error('请选择课表文件');await requirePrivacyReview('',[file.value],'',consent.value);const body=new FormData();body.append('file',file.value);body.append('consent','true');const result=await api('/api/v1/timetable/parse',{method:'POST',body});text.value=result.lines.map((l:any)=>l.text).join('\n');parse();message.value='文件已解析成文字，请核对课程候选；无法确定的行需手工补充。'}catch(e:any){error.value=e.message}}
async function cancelDate(c:Course,event:Event){const day=(event.target as HTMLInputElement).value;if(day){c.cancelledDates.push(day);await persist();message.value='该次课程已取消；临时调课请另增对应课程。'}}
</script>
<template><div class="page page--utility"><AppHeader title="本机课表"/><GuideLink topic="timetable" label="学期、单双周和课程候选确认说明"/><p v-if="error" role="alert" class="notice notice--danger">{{error}}</p><p v-if="message" role="status" class="notice notice--success">{{message}}</p><p class="notice">课表保存在当前设备，图片/PDF解析须明确确认上传；课程候选核对后才参与排程。</p>
<section class="surface-card form-card"><label>学期第一周周一<input v-model="semesterStart" type="date"></label><label>学期结束日期<input v-model="semesterEnd" type="date"></label></section>
<form class="surface-card form-card" @submit.prevent="add"><h2>手工录入课程</h2><label>课程名称<input v-model="form.title" required maxlength="200"></label><label>星期<select v-model.number="form.weekday" aria-label="星期"><option v-for="day in 7" :key="day" :value="day">周{{'一二三四五六日'[day-1]}}</option></select></label><label>课程开始时间<input v-model="form.startTime" type="time" required></label><label>课程结束时间<input v-model="form.endTime" type="time" required></label><div class="form-grid"><label>开始周次<input v-model.number="form.startWeek" type="number" min="1" max="30"></label><label>结束周次<input v-model.number="form.endWeek" type="number" min="1" max="30"></label></div><label>单双周<select v-model="form.parity" aria-label="单双周"><option value="all">每周</option><option value="odd">单周</option><option value="even">双周</option></select></label><button class="button button--primary">保存课程</button></form>
<section class="surface-card form-card"><h2>从文字或文件整理</h2><label>课表文字<textarea v-model="text" rows="5" maxlength="20000" placeholder="高等数学 周一 08:00-10:00 第1-18周"></textarea></label><button class="button button--secondary" @click="parse">整理课程候选</button><label>图片/PDF/Word课表<input type="file" accept="image/png,image/jpeg,application/pdf,.docx" @change="file=($event.target as HTMLInputElement).files?.[0]||null;consent=false"></label><label class="consent-row"><input v-model="consent" type="checkbox">已核对课表文件隐私，同意上传解析</label><button class="button button--secondary" :disabled="!consent||!file" @click="upload">确认解析课表文件</button><article v-for="c in candidates" :key="c.id"><h3>{{c.title}}</h3><p>{{c.evidence.text}}</p><button class="button button--secondary" @click="confirmCourse(c)">确认此课程</button></article><p v-if="unparsed.length">{{unparsed.length}} 行无法可靠识别，未加入课表，请手工补充。</p></section>
<section class="surface-card"><h2>已确认课程</h2><p v-if="courseConflicts(data.courses).length" class="notice notice--warning">课表有重叠，请核对；排程仍避开全部占用时段。</p><article v-for="c in data.courses" :key="c.id"><h3>{{c.title}}</h3><p>周{{c.weekday}} {{c.startTime}}–{{c.endTime}} · {{c.startWeek}}–{{c.endWeek}}周 · {{c.parity==='all'?'每周':c.parity==='odd'?'单周':'双周'}}</p><blockquote>{{c.evidence.text}}</blockquote><label>取消某次课程<input type="date" @change="cancelDate(c,$event)"></label><p v-if="c.cancelledDates.length">已取消：{{c.cancelledDates.join('、')}}</p><button class="button button--secondary" @click="remove(c.id)">删除课程</button></article><button class="button button--secondary" @click="demo">加入合成示例课表</button></section><RouterLink class="button button--primary" to="/plan?tab=schedule">按课表安排任务</RouterLink></div></template>
<style scoped>textarea{width:100%;box-sizing:border-box}article{border-top:1px solid #ddd;padding:12px 0}blockquote{margin:8px 0;overflow-wrap:anywhere}label{display:block;margin:8px 0}</style>
